    return {
        restrict: "A",
        scope: {
            modalVisible: "="
        },
        link: function (scope, element, attrs) {
            scope.showLoading = function (visible) {
                if (visible) {
                    element.modal({ show: true, keyboard: false, backdrop: 'static' });
                }
                else {
                    element.modal("hide");
                }
            }
            //Check to see if the modal-visible attribute exists
